<?php

namespace Database\Seeders;

use App\Models\Lesson;
use App\Models\Path;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;

/**
 * يزرع المسارات الستة ومواضيعها للمراحل الثلاث (ابتدائي / متوسط / ثانوي).
 *
 * تحذير: هذا السيدر يحذف (truncate) المسارات والدروس القديمة وكل ما يرتبط بها
 * من اشتراكات وشهادات وأوسمة واختبارات وفيديوهات وحزم SCORM.
 */
class PathsSeeder extends Seeder
{
    public function run(): void
    {
        $this->truncateOldPaths();

        foreach ($this->paths() as $pathData) {
            $topics = $pathData['topics'];
            unset($pathData['topics']);

            $path = Path::create($pathData + ['is_active' => true]);

            foreach ($topics as $gradeLevel => $stageTopics) {
                foreach ($stageTopics as $index => $topic) {
                    Lesson::create([
                        'path_id'     => $path->id,
                        'title'       => $topic['title'],
                        'description' => $topic['goal'],
                        'grade_level' => $gradeLevel,
                        'sort_order'  => $index + 1,
                        'is_active'   => true,
                    ]);
                }
            }
        }
    }

    /**
     * تفريغ المسارات والدروس وكل الجداول المرتبطة بها.
     * الترتيب من الأبناء إلى الآباء، مع تعطيل فحص المفاتيح الأجنبية أثناء التفريغ.
     */
    private function truncateOldPaths(): void
    {
        $tables = [
            'scorm_tracking',
            'lesson_progress',
            'certificates',
            'student_badges',
            'badges',
            'quiz_options',
            'quiz_questions',
            'quizzes',
            'videos',
            'scorm_packages',
            'enrollments',
            'lessons',
            'paths',
        ];

        Schema::disableForeignKeyConstraints();

        foreach ($tables as $table) {
            if (Schema::hasTable($table)) {
                DB::table($table)->truncate();
            }
        }

        Schema::enableForeignKeyConstraints();
    }

    private function paths(): array
    {
        return [
            $this->creativityPath(),
            $this->communicationPath(),
            $this->decisionMakingPath(),
            $this->financePath(),
            $this->emotionalPath(),
            $this->digitalPath(),
        ];
    }

